"""Jason Stys: generated file catalog and exact source navigation; lines: docs/SOURCE_MAP.md.

Python and TypeScript use ASTs; Rego declarations and SQL schema lines use lexical navigation.
"""

import ast
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
EXCLUDE = {
    ".git",
    ".venv",
    ".runtime",
    "target",
    "node_modules",
    "dist",
    "coverage",
    "__pycache__",
    ".pytest_cache",
    ".ruff_cache",
    "test-results",
    "playwright-report",
}
SPECIAL = {
    "package.json": "Exact frontend/test dependency pins and reproducible task commands.",
    "package-lock.json": "Resolved npm dependency versions and integrity hashes.",
    "requirements.lock": "Production Python transitive dependency hash lock.",
    "requirements-dev.lock": "Production and development Python dependency hash lock.",
    "tsconfig.json": "Strict TypeScript compiler settings for UI, tests and config.",
    "LICENSE": "MIT license for original source; third-party tools retain their licenses.",
    "docs/FILE_CATALOG.md": "Generated file-by-file responsibility catalog.",
    "docs/SOURCE_MAP.md": "Generated declaration/variable physical line navigation.",
}


def files():
    """Exclude dependencies, runtime state and generated build/test results from public navigation."""
    result = []
    for directory, children, names in os.walk(ROOT):
        children[:] = [child for child in children if child not in EXCLUDE]
        result.extend(Path(directory) / name for name in names if not name.startswith(".coverage"))
    # Include both generated deliverables on the first invocation as well as later checks.
    result.extend([ROOT / "docs/FILE_CATALOG.md", ROOT / "docs/SOURCE_MAP.md"])
    return sorted(set(result), key=lambda p: p.relative_to(ROOT).as_posix())


def render():
    """Generate AST declaration maps plus native lexical declaration lines without executing source."""
    catalog = [
        "# File catalog",
        "",
        "By Jason Stys. Generated by `python tools/docs_index.py`.",
        "",
        "| File | Responsibility |",
        "| --- | --- |",
    ]
    source = [
        "# Source declaration map",
        "",
        "By Jason Stys. Headers link here for current exact physical lines.",
        "Python/TypeScript ASTs index declarations, parameters and bindings. Rego lists rule/assignment/some/every lines; SQL lists non-comment schema lines. Lexical maps are navigation, not complete semantic symbol tables.",
        "",
        "| File | Line | Declaration / variable |",
        "| --- | ---: | --- |",
    ]
    for path in files():
        relative = path.relative_to(ROOT).as_posix()
        content = path.read_text(encoding="utf-8") if path.is_file() else ""
        description = SPECIAL.get(relative) or next(
            (
                line.strip(' #/*!-"<>')
                for line in content.splitlines()[:12]
                if "Jason Stys:" in line
            ),
            None,
        )
        if description is None:
            raise ValueError(f"Missing file responsibility: {relative}")
        catalog.append(f"| `{relative}` | {description.replace('|', '/')} |")
        records = set()
        if path.suffix == ".py":
            for node in ast.walk(ast.parse(content)):
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                    args = (
                        "class"
                        if isinstance(node, ast.ClassDef)
                        else ", ".join(a.arg for a in node.args.args)
                    )
                    records.add((node.lineno, f"{node.name}({args})"))
                elif isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
                    records.add((node.lineno, node.id))
        if path.suffix == ".rego":
            for line, value in enumerate(content.splitlines(), 1):
                if not value.lstrip().startswith("#") and (
                    ":=" in value
                    or re.search(r"\b(?:some|every)\b", value)
                    or re.match(r"^[a-zA-Z_][a-zA-Z_0-9]*(?:\([^)]*\))?\s+if", value)
                ):
                    records.add((line, value.strip().replace("|", "/")))
        if path.suffix == ".sql":
            records.update(
                (line, value.strip())
                for line, value in enumerate(content.splitlines(), 1)
                if value.strip() and not value.lstrip().startswith("--")
            )
        source.extend(f"| `{relative}` | {line} | `{name}` |" for line, name in sorted(records))
    node = shutil.which("node")
    if node is None:
        raise RuntimeError("Node.js required for TypeScript AST navigation")
    source.extend(
        subprocess.check_output([node, "tools/source_index.mjs"], cwd=ROOT, text=True, timeout=30)
        .strip()
        .splitlines()
    )
    return {
        "docs/FILE_CATALOG.md": "\n".join(catalog) + "\n",
        "docs/SOURCE_MAP.md": "\n".join(source) + "\n",
    }


def main():
    """Generate navigation locally or fail if committed documentation is stale in CI."""
    for relative, content in render().items():
        path = ROOT / relative
        if "--check" in sys.argv:
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                raise SystemExit(f"Stale {relative}: run python tools/docs_index.py")
        else:
            path.write_text(content, encoding="utf-8")
    print(f"Source/file navigation verified for {len(files())} files")


if __name__ == "__main__":
    main()
